button.content:
import * as React from "react";
import { Loader2 } from "lucide-react";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "default" | "secondary" | "outline" | "ghost" | "destructive";
  size?: "sm" | "md" | "lg";
  isLoading?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className = "",
      variant = "default",
      size = "md",
      isLoading = false,
      leftIcon,
      rightIcon,
      disabled,
      children,
      ...props
    },
    ref
  ) => {
    const baseStyles =
      "inline-flex items-center justify-center font-medium transition-all duration-150 select-none outline-none focus-visible:ring-2 focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none cursor-pointer rounded-md";

    const variantStyles = {
      default:
        "bg-primary text-primary-foreground hover:bg-primary-hover focus-visible:ring-ring shadow-sm",
      secondary:
        "bg-secondary text-foreground hover:bg-surface-tertiary focus-visible:ring-border border border-border",
      outline:
        "bg-transparent text-foreground border border-border hover:bg-secondary focus-visible:ring-border",
      ghost:
        "bg-transparent text-foreground hover:bg-secondary focus-visible:ring-border",
      destructive:
        "bg-red-600 text-white hover:bg-red-700 focus-visible:ring-red-500 shadow-sm",
    };

    const sizeStyles = {
      sm: "h-8 px-3 text-xs gap-1.5",
      md: "h-10 px-4 text-sm gap-2",
      lg: "h-12 px-6 text-base gap-2.5",
    };

    return (
      <button
        ref={ref}
        disabled={disabled || isLoading}
        className={`${baseStyles} ${variantStyles[variant]} ${sizeStyles[size]} ${className}`}
        {...props}
      >
        {isLoading ? (
          <Loader2 className="h-4 w-4 animate-spin text-current" />
        ) : (
          leftIcon
        )}
        {children}
        {!isLoading && rightIcon}
      </button>
    );
  }
);
Button.displayName = "Button";

card.content:
import * as React from "react";

export function Card({ className = "", ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={`rounded-lg border border-border bg-card text-card-foreground shadow-sm transition-shadow hover:shadow-md ${className}`}
      {...props}
    />
  );
}

export function CardHeader({ className = "", ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={`flex flex-col space-y-1.5 p-6 ${className}`} {...props} />;
}

export function CardTitle({ className = "", ...props }: React.HTMLAttributes<HTMLHeadingElement>) {
  return (
    <h3
      className={`text-lg font-semibold leading-none tracking-tight text-card-foreground ${className}`}
      {...props}
    />
  );
}

export function CardDescription({ className = "", ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={`text-sm text-muted-foreground ${className}`}
      {...props}
    />
  );
}

export function CardContent({ className = "", ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={`p-6 pt-0 ${className}`} {...props} />;
}

export function CardFooter({ className = "", ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={`flex items-center p-6 pt-0 border-t border-border mt-4 ${className}`}
      {...props}
    />
  );
}

input.content:
import * as React from "react";

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  error?: string;
  helperText?: string;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  (
    {
      className = "",
      label,
      error,
      helperText,
      leftIcon,
      rightIcon,
      id,
      disabled,
      ...props
    },
    ref
  ) => {
    const inputId = id || React.useId();

    return (
      <div className="w-full flex flex-col gap-1.5">
        {label && (
          <label
            htmlFor={inputId}
            className="text-xs font-semibold text-foreground select-none"
          >
            {label}
          </label>
        )}
        <div className="relative flex items-center w-full">
          {leftIcon && (
            <div className="absolute left-3 flex items-center pointer-events-none text-muted-foreground">
              {leftIcon}
            </div>
          )}
          <input
            id={inputId}
            ref={ref}
            disabled={disabled}
            aria-invalid={!!error}
            className={`w-full h-10 rounded-md border bg-background text-foreground px-3 text-sm placeholder:text-muted-foreground transition-colors outline-none focus:ring-2 focus:ring-ring focus:border-ring disabled:opacity-50 disabled:bg-muted disabled:cursor-not-allowed ${
              leftIcon ? "pl-9" : ""
            } ${rightIcon ? "pr-9" : ""} ${
              error
                ? "border-red-500 focus:ring-red-500"
                : "border-border hover:border-border-strong"
            } ${className}`}
            {...props}
          />
          {rightIcon && (
            <div className="absolute right-3 flex items-center pointer-events-none text-muted-foreground">
              {rightIcon}
            </div>
          )}
        </div>
        {error && <span className="text-xs text-red-500 font-medium">{error}</span>}
        {helperText && !error && (
          <span className="text-xs text-muted-foreground">{helperText}</span>
        )}
      </div>
    );
  }
);
Input.displayName = "Input";

badge.content:
import * as React from "react";

export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: "default" | "brand" | "outline" | "success" | "warning" | "destructive";
  size?: "sm" | "md";
}

export function Badge({
  className = "",
  variant = "default",
  size = "md",
  children,
  ...props
}: BadgeProps) {
  const variantStyles = {
    default: "bg-secondary text-foreground border-transparent",
    brand: "bg-brand-subtle text-brand border-brand/20 font-semibold",
    outline: "bg-transparent text-foreground border-border-strong",
    success: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20",
    warning: "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20",
    destructive: "bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/20",
  };

  const sizeStyles = {
    sm: "px-2 py-0.5 text-[11px]",
    md: "px-2.5 py-1 text-xs",
  };

  return (
    <div
      className={`inline-flex items-center gap-1 font-medium rounded-full border transition-colors select-none ${variantStyles[variant]} ${sizeStyles[size]} ${className}`}
      {...props}
    >
      {children}
    </div>
  );
}

dialog.content:
"use client";

import * as React from "react";
import { X } from "lucide-react";

interface DialogContextType {
  open: boolean;
  setOpen: (open: boolean) => void;
}

const DialogContext = React.createContext<DialogContextType | undefined>(undefined);

export function Dialog({
  children,
  open: controlledOpen,
  onOpenChange,
}: {
  children: React.ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(false);
  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : uncontrolledOpen;

  const setOpen = React.useCallback(
    (nextOpen: boolean) => {
      if (!isControlled) setUncontrolledOpen(nextOpen);
      onOpenChange?.(nextOpen);
    },
    [isControlled, onOpenChange]
  );

  return (
    <DialogContext.Provider value={{ open, setOpen }}>
      {children}
    </DialogContext.Provider>
  );
}

export function DialogTrigger({
  asChild,
  children,
}: {
  asChild?: boolean;
  children: React.ReactElement<{ onClick?: React.MouseEventHandler }>;
}) {
  const ctx = React.useContext(DialogContext);
  if (!ctx) throw new Error("DialogTrigger must be used inside Dialog");

  return React.cloneElement(children, {
    onClick: (e: React.MouseEvent) => {
      children.props.onClick?.(e);
      ctx.setOpen(true);
    },
  });
}

export function DialogContent({
  children,
  className = "",
}: {
  children: React.ReactNode;
  className?: string;
}) {
  const ctx = React.useContext(DialogContext);
  if (!ctx) throw new Error("DialogContent must be used inside Dialog");

  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") ctx.setOpen(false);
    };
    if (ctx.open) {
      document.body.style.overflow = "hidden";
      window.addEventListener("keydown", handleKeyDown);
    }
    return () => {
      document.body.style.overflow = "unset";
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [ctx]);

  if (!ctx.open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="fixed inset-0 bg-black/60 backdrop-blur-xs transition-opacity"
        onClick={() => ctx.setOpen(false)}
      />
      <div
        role="dialog"
        aria-modal="true"
        className={`relative z-10 w-full max-w-lg rounded-lg border border-border bg-card p-6 shadow-2xl text-card-foreground ${className}`}
      >
        <button
          onClick={() => ctx.setOpen(false)}
          className="absolute right-4 top-4 rounded-sm opacity-70 hover:opacity-100 transition-opacity cursor-pointer text-foreground"
          aria-label="Close dialog"
        >
          <X size={18} />
        </button>
        {children}
      </div>
    </div>
  );
}

export function DialogHeader({ className = "", ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={`flex flex-col space-y-1.5 text-left mb-4 ${className}`} {...props} />;
}

export function DialogTitle({ className = "", ...props }: React.HTMLAttributes<HTMLHeadingElement>) {
  return <h2 className={`text-lg font-semibold text-foreground ${className}`} {...props} />;
}

export function DialogDescription({ className = "", ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className={`text-sm text-muted-foreground ${className}`} {...props} />;
}

export function DialogFooter({ className = "", ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={`flex flex-wrap justify-end gap-2 mt-6 ${className}`} {...props} />;
}

tabs.content:
"use client";

import * as React from "react";

interface TabsContextType {
  value: string;
  onValueChange: (val: string) => void;
}

const TabsContext = React.createContext<TabsContextType | undefined>(undefined);

export function Tabs({
  defaultValue,
  value: controlledValue,
  onValueChange,
  children,
  className = "",
}: {
  defaultValue?: string;
  value?: string;
  onValueChange?: (val: string) => void;
  children: React.ReactNode;
  className?: string;
}) {
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue || "");
  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : uncontrolledValue;

  const handleValueChange = (newVal: string) => {
    if (!isControlled) setUncontrolledValue(newVal);
    onValueChange?.(newVal);
  };

  return (
    <TabsContext.Provider value={{ value, onValueChange: handleValueChange }}>
      <div className={`w-full flex flex-col ${className}`}>{children}</div>
    </TabsContext.Provider>
  );
}

export function TabsList({ className = "", ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      role="tablist"
      className={`inline-flex items-center gap-1 p-1 bg-muted border border-border rounded-md self-start ${className}`}
      {...props}
    />
  );
}

export function TabsTrigger({
  value,
  children,
  className = "",
}: {
  value: string;
  children: React.ReactNode;
  className?: string;
}) {
  const ctx = React.useContext(TabsContext);
  if (!ctx) throw new Error("TabsTrigger must be used inside Tabs");

  const isSelected = ctx.value === value;

  return (
    <button
      role="tab"
      type="button"
      aria-selected={isSelected}
      onClick={() => ctx.onValueChange(value)}
      className={`px-3.5 py-1.5 text-xs font-medium rounded-sm transition-all cursor-pointer ${
        isSelected
          ? "bg-card text-foreground shadow-sm font-semibold"
          : "text-muted-foreground hover:text-foreground"
      } ${className}`}
    >
      {children}
    </button>
  );
}

export function TabsContent({
  value,
  children,
  className = "",
}: {
  value: string;
  children: React.ReactNode;
  className?: string;
}) {
  const ctx = React.useContext(TabsContext);
  if (!ctx) throw new Error("TabsContent must be used inside Tabs");

  if (ctx.value !== value) return null;

  return (
    <div role="tabpanel" className={`mt-4 focus-visible:outline-none ${className}`}>
      {children}
    </div>
  );
}

accordion.content:
"use client";

import * as React from "react";
import { ChevronDown, Plus, Minus } from "lucide-react";

export type AccordionVariant =
  | "morph"
  | "minimal"
  | "outlined"
  | "nested"
  | "bordered"
  | "cards"
  | "filled";

export type AccordionIndicator = "chevron" | "plus" | "morph" | "arrow" | "none";
export type AccordionAnimation = "smooth" | "spring" | "none";

interface AccordionContextValue {
  expanded: string[];
  toggleItem: (value: string) => void;
  type: "single" | "multiple";
  variant: AccordionVariant;
  indicator: AccordionIndicator;
  animation: AccordionAnimation;
  disabled?: boolean;
}

const AccordionContext = React.createContext<AccordionContextValue | null>(null);

export function useAccordion() {
  const context = React.useContext(AccordionContext);
  if (!context) {
    throw new Error("Accordion compound components must be used within an <Accordion />");
  }
  return context;
}

export interface AccordionProps extends React.HTMLAttributes<HTMLDivElement> {
  type?: "single" | "multiple";
  variant?: AccordionVariant;
  indicator?: AccordionIndicator;
  animation?: AccordionAnimation;
  defaultValue?: string | string[];
  value?: string | string[];
  onValueChange?: (value: string | string[]) => void;
  collapsible?: boolean;
  disabled?: boolean;
}

export const Accordion = React.forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      type = "single",
      variant = "morph",
      indicator = "chevron",
      animation = "smooth",
      defaultValue,
      value: controlledValue,
      onValueChange,
      collapsible = true,
      disabled = false,
      className = "",
      children,
      ...props
    },
    ref
  ) => {
    const initialExpanded = React.useMemo(() => {
      if (defaultValue) {
        return Array.isArray(defaultValue) ? defaultValue : [defaultValue];
      }
      return [];
    }, [defaultValue]);

    const [uncontrolledValue, setUncontrolledValue] = React.useState<string[]>(initialExpanded);
    const isControlled = controlledValue !== undefined;
    const currentExpanded = React.useMemo(() => {
      return isControlled
        ? Array.isArray(controlledValue)
          ? controlledValue
          : controlledValue
          ? [controlledValue]
          : []
        : uncontrolledValue;
    }, [isControlled, controlledValue, uncontrolledValue]);

    const toggleItem = React.useCallback(
      (itemValue: string) => {
        if (disabled) return;

        let next: string[];
        if (type === "single") {
          if (currentExpanded.includes(itemValue)) {
            next = collapsible ? [] : currentExpanded;
          } else {
            next = [itemValue];
          }
        } else {
          if (currentExpanded.includes(itemValue)) {
            next = currentExpanded.filter((v) => v !== itemValue);
          } else {
            next = [...currentExpanded, itemValue];
          }
        }

        if (!isControlled) {
          setUncontrolledValue(next);
        }

        if (onValueChange) {
          if (type === "single") {
            (onValueChange as (val: string) => void)(next[0] || "");
          } else {
            (onValueChange as (val: string[]) => void)(next);
          }
        }
      },
      [disabled, type, currentExpanded, collapsible, isControlled, onValueChange]
    );

    const variantRootClasses: Record<AccordionVariant, string> = {
      morph: "mf-accordion-morph space-y-2.5",
      minimal: "mf-accordion-minimal divide-y divide-[#F1F4F9]",
      outlined: "mf-accordion-outlined space-y-3",
      nested: "mf-accordion-nested space-y-2",
      bordered: "border border-border rounded-xl divide-y divide-border bg-card shadow-xs overflow-hidden",
      cards: "space-y-2.5 bg-transparent",
      filled: "bg-surface-secondary border border-border/80 rounded-xl divide-y divide-border/60 overflow-hidden",
    };

    return (
      <AccordionContext.Provider
        value={{
          expanded: currentExpanded,
          toggleItem,
          type,
          variant,
          indicator,
          animation,
          disabled,
        }}
      >
        <div
          ref={ref}
          data-variant={variant}
          data-animation={animation}
          className={`${variantRootClasses[variant] || ""} ${className}`}
          {...props}
        >
          {children}
        </div>
      </AccordionContext.Provider>
    );
  }
);
Accordion.displayName = "Accordion";

/* -------------------------------------------------------------------------------------------------
 * AccordionItem
 * -----------------------------------------------------------------------------------------------*/

interface AccordionItemContextValue {
  value: string;
  isOpen: boolean;
  disabled: boolean;
  triggerId: string;
  contentId: string;
}

const AccordionItemContext = React.createContext<AccordionItemContextValue | null>(null);

export function useAccordionItem() {
  const context = React.useContext(AccordionItemContext);
  if (!context) {
    throw new Error("AccordionItem components must be used within an <AccordionItem />");
  }
  return context;
}

export interface AccordionItemProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
  disabled?: boolean;
}

export const AccordionItem = React.forwardRef<HTMLDivElement, AccordionItemProps>(
  ({ value, disabled = false, className = "", children, ...props }, ref) => {
    const { expanded, variant, disabled: rootDisabled } = useAccordion();
    const isOpen = expanded.includes(value);
    const isItemDisabled = Boolean(disabled || rootDisabled);
    const id = React.useId();
    const triggerId = `accordion-trigger-${id}`;
    const contentId = `accordion-content-${id}`;

    const variantItemClasses: Record<AccordionVariant, string> = {
      morph: `mf-morph-item rounded-xl border transition-all duration-200 bg-white ${
        isOpen
          ? "border-[#C7D2FE] shadow-[0_4px_16px_-2px_rgba(81,69,255,0.08)]"
          : "border-[#E5E7EB] hover:border-[#D1D5DB]"
      }`,
      minimal: "mf-minimal-item",
      outlined: `mf-outlined-item rounded-xl border transition-all duration-200 bg-white ${
        isOpen
          ? "border-[#C7D2FE] shadow-[0_2px_10px_rgba(81,69,255,0.06)]"
          : "border-[#E5E7EB] hover:border-[#D1D5DB]"
      }`,
      nested: "mf-nested-item",
      bordered: "group transition-colors",
      cards: `rounded-xl border transition-all duration-200 bg-card overflow-hidden ${
        isOpen
          ? "border-primary/40 shadow-sm ring-1 ring-primary/20"
          : "border-border hover:border-border-strong hover:shadow-xs"
      }`,
      filled: "group transition-colors",
    };

    return (
      <AccordionItemContext.Provider
        value={{ value, isOpen, disabled: isItemDisabled, triggerId, contentId }}
      >
        <div
          ref={ref}
          data-state={isOpen ? "open" : "closed"}
          data-disabled={isItemDisabled ? "" : undefined}
          className={`${variantItemClasses[variant] || ""} ${
            isItemDisabled ? "opacity-50 pointer-events-none" : ""
          } ${className}`}
          {...props}
        >
          {children}
        </div>
      </AccordionItemContext.Provider>
    );
  }
);
AccordionItem.displayName = "AccordionItem";

/* -------------------------------------------------------------------------------------------------
 * AccordionTrigger
 * -----------------------------------------------------------------------------------------------*/

export interface AccordionTriggerProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  subtitle?: React.ReactNode;
  badge?: React.ReactNode;
  hideIndicator?: boolean;
}

export const AccordionTrigger = React.forwardRef<HTMLButtonElement, AccordionTriggerProps>(
  (
    {
      className = "",
      children,
      icon,
      subtitle,
      badge,
      hideIndicator = false,
      onClick,
      ...props
    },
    ref
  ) => {
    const { toggleItem, variant, indicator } = useAccordion();
    const itemContext = React.useContext(AccordionItemContext);

    if (!itemContext) {
      throw new Error("AccordionTrigger must be used inside an <AccordionItem />");
    }

    const { value, isOpen, disabled, triggerId, contentId } = itemContext;

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (disabled) return;
      toggleItem(value);
      onClick?.(e);
    };

    const renderIndicator = () => {
      if (hideIndicator || indicator === "none") return null;

      if (indicator === "morph") {
        return (
          <span
            className={`shrink-0 inline-flex items-center justify-center w-6 h-6 rounded-md transition-all duration-200 ${
              isOpen
                ? "bg-[#EEF2FF] text-[#5145FF]"
                : "bg-[#F3F4F6] text-[#6B7280] group-hover:text-[#111827]"
            }`}
          >
            {isOpen ? <Minus size={14} /> : <Plus size={14} />}
          </span>
        );
      }

      if (indicator === "plus") {
        return (
          <span
            className={`shrink-0 inline-flex items-center justify-center w-6 h-6 rounded-md transition-all duration-200 ${
              isOpen
                ? "rotate-45 text-[#5145FF] bg-[#EEF2FF]"
                : "text-[#6B7280] bg-[#F3F4F6] group-hover:text-[#111827]"
            }`}
          >
            <Plus size={14} />
          </span>
        );
      }

      // Default chevron
      return (
        <ChevronDown
          size={18}
          className={`shrink-0 transition-transform duration-200 ${
            isOpen ? "rotate-180 text-[#5145FF]" : "text-[#9CA3AF] group-hover:text-[#6B7280]"
          }`}
          aria-hidden="true"
        />
      );
    };

    return (
      <button
        ref={ref}
        type="button"
        id={triggerId}
        aria-controls={contentId}
        aria-expanded={isOpen}
        disabled={disabled}
        onClick={handleClick}
        className={`group flex w-full items-center justify-between font-medium outline-none cursor-pointer transition-colors select-none text-left ${className}`}
        {...props}
      >
        <div className="flex items-center gap-3 min-w-0 pr-3">
          {icon && <span className="shrink-0">{icon}</span>}
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2">
              <span className="font-semibold text-sm text-[#111827] group-hover:text-[#5145FF] transition-colors">
                {children}
              </span>
              {badge && <span className="shrink-0">{badge}</span>}
            </div>
            {subtitle && (
              <div className="text-xs text-[#6B7280] mt-0.5 truncate font-normal">
                {subtitle}
              </div>
            )}
          </div>
        </div>

        {renderIndicator()}
      </button>
    );
  }
);
AccordionTrigger.displayName = "AccordionTrigger";

/* -------------------------------------------------------------------------------------------------
 * AccordionContent
 * -----------------------------------------------------------------------------------------------*/

export type AccordionContentProps = React.HTMLAttributes<HTMLDivElement>;

export const AccordionContent = React.forwardRef<HTMLDivElement, AccordionContentProps>(
  ({ className = "", children, ...props }, ref) => {
    const { animation } = useAccordion();
    const itemContext = React.useContext(AccordionItemContext);

    if (!itemContext) {
      throw new Error("AccordionContent must be used inside an <AccordionItem />");
    }

    const { isOpen, contentId, triggerId } = itemContext;

    const animationClasses: Record<AccordionAnimation, string> = {
      none: "transition-none",
      smooth: "transition-[grid-template-rows] duration-200 ease-out",
      spring: "transition-[grid-template-rows] duration-350 ease-[cubic-bezier(0.34,1.35,0.64,1)]",
    };

    return (
      <div
        ref={ref}
        id={contentId}
        role="region"
        aria-labelledby={triggerId}
        data-state={isOpen ? "open" : "closed"}
        className={`grid motion-reduce:transition-none data-[state=closed]:grid-rows-[0fr] data-[state=open]:grid-rows-[1fr] ${
          animationClasses[animation] || animationClasses.smooth
        }`}
      >
        <div className="overflow-hidden min-h-0">
          <div className={`text-sm text-[#4B5563] leading-relaxed ${className}`} {...props}>
            {children}
          </div>
        </div>
      </div>
    );
  }
);
AccordionContent.displayName = "AccordionContent";

alert.content:
"use client";

import * as React from "react";
import {
  Info,
  CheckCircle2,
  AlertTriangle,
  AlertOctagon,
  X,
  Sparkles,
  HelpCircle,
} from "lucide-react";

export type AlertStatus =
  | "brand"
  | "info"
  | "success"
  | "warning"
  | "destructive"
  | "neutral";

export type AlertDesign =
  | "morph"
  | "subtle"
  | "rail"
  | "card"
  | "solid"
  | "outline"
  | "floating";

export type AlertSize = "sm" | "md" | "lg";

export interface AlertProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  status?: AlertStatus;
  /** Backwards compatibility alias for status */
  variant?: AlertStatus;
  design?: AlertDesign;
  size?: AlertSize;
  icon?: React.ReactNode;
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: React.ReactNode;
  onClose?: () => void;
}

export function getDefaultAlertIcon(status: AlertStatus, size: AlertSize = "md") {
  const iconSize = size === "sm" ? 15 : size === "lg" ? 20 : 17;
  switch (status) {
    case "brand":
      return <Sparkles size={iconSize} />;
    case "info":
      return <Info size={iconSize} />;
    case "success":
      return <CheckCircle2 size={iconSize} />;
    case "warning":
      return <AlertTriangle size={iconSize} />;
    case "destructive":
      return <AlertOctagon size={iconSize} />;
    case "neutral":
      return <HelpCircle size={iconSize} />;
  }
}

export const Alert = React.forwardRef<HTMLDivElement, AlertProps>(
  (
    {
      status,
      variant = "brand",
      design = "morph",
      size = "md",
      icon,
      title,
      description,
      action,
      onClose,
      className = "",
      children,
      ...props
    },
    ref
  ) => {
    const activeStatus = status || variant;
    const [isDismissed, setIsDismissed] = React.useState(false);

    if (isDismissed) {
      return null;
    }

    const handleDismiss = () => {
      setIsDismissed(true);
      onClose?.();
    };

    const displayIcon =
      icon !== undefined ? icon : getDefaultAlertIcon(activeStatus, size);

    // Dynamic container styles
    const getContainerStyles = (): string => {
      // 1. Signature Morph (Elevated white card with soft ambient color tint & refined border)
      if (design === "morph") {
        const morphStyles = {
          brand: "bg-white border-[#E0E7FF] hover:border-[#C7D2FE] shadow-[0_4px_20px_-2px_rgba(81,69,255,0.07)] text-[#111827]",
          info: "bg-white border-blue-100 hover:border-blue-200 shadow-[0_4px_20px_-2px_rgba(59,130,246,0.07)] text-[#111827]",
          success: "bg-white border-emerald-100 hover:border-emerald-200 shadow-[0_4px_20px_-2px_rgba(16,185,129,0.07)] text-[#111827]",
          warning: "bg-white border-amber-100 hover:border-amber-200 shadow-[0_4px_20px_-2px_rgba(245,158,11,0.07)] text-[#111827]",
          destructive: "bg-white border-red-100 hover:border-red-200 shadow-[0_4px_20px_-2px_rgba(239,68,68,0.07)] text-[#111827]",
          neutral: "bg-white border-[#E5E7EB] hover:border-[#D1D5DB] shadow-[0_4px_20px_-2px_rgba(0,0,0,0.03)] text-[#111827]",
        }[activeStatus];

        return `border rounded-2xl ${morphStyles}`;
      }

      // 2. Floating Glass (Floating pill/banner with backdrop blur)
      if (design === "floating") {
        const floatingGlow = {
          brand: "shadow-[0_8px_30px_rgba(81,69,255,0.12)] border-[#E0E7FF]/80",
          info: "shadow-[0_8px_30px_rgba(59,130,246,0.12)] border-blue-200/80",
          success: "shadow-[0_8px_30px_rgba(16,185,129,0.12)] border-emerald-200/80",
          warning: "shadow-[0_8px_30px_rgba(245,158,11,0.12)] border-amber-200/80",
          destructive: "shadow-[0_8px_30px_rgba(239,68,68,0.12)] border-red-200/80",
          neutral: "shadow-[0_8px_30px_rgba(0,0,0,0.06)] border-[#E5E7EB]",
        }[activeStatus];

        return `backdrop-blur-md bg-white/95 border rounded-2xl ${floatingGlow} text-[#111827]`;
      }

      // 3. Rail (4px left border accent)
      if (design === "rail") {
        const borderRail = {
          brand: "border-l-[#5145FF]",
          info: "border-l-blue-500",
          success: "border-l-emerald-500",
          warning: "border-l-amber-500",
          destructive: "border-l-red-500",
          neutral: "border-l-gray-400",
        }[activeStatus];

        return `bg-white text-[#111827] border border-[#E5E7EB] border-l-4 ${borderRail} rounded-xl shadow-xs`;
      }

      // 4. Solid (Vibrant filled banner for critical notices)
      if (design === "solid") {
        switch (activeStatus) {
          case "brand":
            return "bg-[#5145FF] text-white border-transparent shadow-sm rounded-xl";
          case "info":
            return "bg-blue-600 text-white border-transparent shadow-sm rounded-xl";
          case "success":
            return "bg-emerald-600 text-white border-transparent shadow-sm rounded-xl";
          case "warning":
            return "bg-amber-500 text-white border-transparent shadow-sm rounded-xl";
          case "destructive":
            return "bg-red-600 text-white border-transparent shadow-sm rounded-xl";
          case "neutral":
            return "bg-[#111827] text-white border-transparent shadow-sm rounded-xl";
        }
      }

      // 5. Card (Neutral boxed card)
      if (design === "card") {
        return "bg-white text-[#111827] border border-[#E5E7EB] rounded-xl shadow-xs hover:border-[#D1D5DB] transition-colors";
      }

      // 6. Outline (Clean transparent background with colored border)
      if (design === "outline") {
        const outlineColors = {
          brand: "border-[#5145FF]/40 text-[#111827]",
          info: "border-blue-500/40 text-[#111827]",
          success: "border-emerald-500/40 text-[#111827]",
          warning: "border-amber-500/40 text-[#111827]",
          destructive: "border-red-500/40 text-[#111827]",
          neutral: "border-[#9CA3AF] text-[#111827]",
        }[activeStatus];

        return `bg-transparent border rounded-xl ${outlineColors}`;
      }

      // 7. Subtle (Default light pastel wash)
      switch (activeStatus) {
        case "brand":
          return "bg-[#EEF2FF] text-[#111827] border border-[#E0E7FF] rounded-xl";
        case "info":
          return "bg-blue-50 text-[#111827] border border-blue-100 rounded-xl";
        case "success":
          return "bg-emerald-50 text-[#111827] border border-emerald-100 rounded-xl";
        case "warning":
          return "bg-amber-50 text-[#111827] border border-amber-100 rounded-xl";
        case "destructive":
          return "bg-red-50 text-[#111827] border border-red-100 rounded-xl";
        case "neutral":
          return "bg-[#F3F4F6] text-[#111827] border border-[#E5E7EB] rounded-xl";
      }
    };

    // Dynamic icon container styles
    const getIconBadgeStyles = (): string => {
      if (design === "solid") {
        return "text-white bg-white/20";
      }

      switch (activeStatus) {
        case "brand":
          return "text-[#5145FF] bg-[#EEF2FF] border border-[#E0E7FF]";
        case "info":
          return "text-blue-600 bg-blue-50 border border-blue-200/60";
        case "success":
          return "text-emerald-600 bg-emerald-50 border border-emerald-200/60";
        case "warning":
          return "text-amber-600 bg-amber-50 border border-amber-200/60";
        case "destructive":
          return "text-red-600 bg-red-50 border border-red-200/60";
        case "neutral":
          return "text-gray-600 bg-gray-100 border border-gray-200";
      }
    };

    const sizePadding = {
      sm: "p-3 gap-2.5 text-xs",
      md: "p-4 gap-3.5 text-sm",
      lg: "p-5 gap-4 text-base",
    }[size];

    const iconBadgeSize = {
      sm: "w-7 h-7 rounded-lg text-xs",
      md: "w-9 h-9 rounded-xl text-sm",
      lg: "w-11 h-11 rounded-2xl text-base",
    }[size];

    return (
      <div
        ref={ref}
        role={activeStatus === "destructive" ? "alert" : "status"}
        aria-live={activeStatus === "destructive" ? "assertive" : "polite"}
        className={`relative flex items-start transition-all duration-200 ${sizePadding} ${getContainerStyles()} ${className}`}
        {...props}
      >
        {displayIcon && (
          <span
            className={`shrink-0 inline-flex items-center justify-center shadow-2xs ${iconBadgeSize} ${getIconBadgeStyles()}`}
          >
            {displayIcon}
          </span>
        )}

        <div className="flex-1 min-w-0 space-y-1">
          {title && (
            <h5
              className={`font-semibold tracking-tight text-sm leading-snug ${
                design === "solid" ? "text-white" : "text-[#111827]"
              }`}
            >
              {title}
            </h5>
          )}
          {description && (
            <div
              className={`leading-relaxed ${
                size === "sm" ? "text-[11.5px]" : "text-xs"
              } ${
                design === "solid"
                  ? "text-white/90"
                  : "text-[#4B5563]"
              }`}
            >
              {description}
            </div>
          )}
          {children}
        </div>

        {action && (
          <div className="shrink-0 self-center pl-2">
            {action}
          </div>
        )}

        {onClose && (
          <button
            type="button"
            onClick={handleDismiss}
            aria-label="Dismiss alert"
            className={`shrink-0 -mr-1 -mt-1 p-1.5 rounded-lg transition-colors focus-visible:outline-none focus-visible:ring-2 cursor-pointer ${
              design === "solid"
                ? "text-white/70 hover:text-white hover:bg-white/15 focus-visible:ring-white"
                : "text-[#9CA3AF] hover:text-[#111827] hover:bg-black/5 focus-visible:ring-[#5145FF]"
            }`}
          >
            <X size={size === "sm" ? 14 : 16} />
          </button>
        )}
      </div>
    );
  }
);
Alert.displayName = "Alert";

// ─── COMPOUND SUBCOMPONENTS ──────────────────────────────────────────────────

export const AlertTitle = React.forwardRef<
  HTMLHeadingElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className = "", children, ...props }, ref) => (
  <h5
    ref={ref}
    className={`font-semibold tracking-tight text-[#111827] text-sm leading-snug ${className}`}
    {...props}
  >
    {children}
  </h5>
));
AlertTitle.displayName = "AlertTitle";

export const AlertDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className = "", children, ...props }, ref) => (
  <div
    ref={ref}
    className={`text-xs text-[#4B5563] leading-relaxed mt-0.5 ${className}`}
    {...props}
  >
    {children}
  </div>
));
AlertDescription.displayName = "AlertDescription";

export const AlertAction = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", children, ...props }, ref) => (
  <div
    ref={ref}
    className={`inline-flex items-center gap-2 ${className}`}
    {...props}
  >
    {children}
  </div>
));
AlertAction.displayName = "AlertAction";

avatar.content:
"use client";

import * as React from "react";

export type AvatarSize = "sm" | "md" | "lg" | "xl";
export type AvatarStatus = "online" | "busy" | "away" | "offline";

interface AvatarContextValue {
  size: AvatarSize;
  imageLoaded: boolean;
  setImageLoaded: (v: boolean) => void;
  imageError: boolean;
  setImageError: (v: boolean) => void;
}

const AvatarContext = React.createContext<AvatarContextValue | null>(null);

function useAvatar() {
  const context = React.useContext(AvatarContext);
  if (!context) {
    throw new Error("Avatar compound components must be used within <Avatar />");
  }
  return context;
}

const sizeClasses: Record<AvatarSize, { container: string; badge: string; text: string }> = {
  sm: { container: "w-8 h-8", badge: "w-2.5 h-2.5 right-0 bottom-0", text: "text-xs" },
  md: { container: "w-10 h-10", badge: "w-3 h-3 right-0 bottom-0", text: "text-sm" },
  lg: { container: "w-12 h-12", badge: "w-3.5 h-3.5 right-0.5 bottom-0.5", text: "text-base" },
  xl: { container: "w-16 h-16", badge: "w-4 h-4 right-1 bottom-1", text: "text-lg" },
};

const statusColors: Record<AvatarStatus, string> = {
  online: "bg-emerald-500",
  busy: "bg-red-500",
  away: "bg-amber-500",
  offline: "bg-slate-400 dark:bg-slate-600",
};

export interface AvatarProps extends React.HTMLAttributes<HTMLDivElement> {
  size?: AvatarSize;
}

export const Avatar = React.forwardRef<HTMLDivElement, AvatarProps>(
  ({ size = "md", className = "", children, ...props }, ref) => {
    const [imageLoaded, setImageLoaded] = React.useState(false);
    const [imageError, setImageError] = React.useState(false);

    return (
      <AvatarContext.Provider
        value={{ size, imageLoaded, setImageLoaded, imageError, setImageError }}
      >
        <div
          ref={ref}
          className={`relative inline-flex shrink-0 rounded-full select-none ${sizeClasses[size].container} ${className}`}
          {...props}
        >
          {children}
        </div>
      </AvatarContext.Provider>
    );
  }
);
Avatar.displayName = "Avatar";

export interface AvatarImageProps
  extends React.ImgHTMLAttributes<HTMLImageElement> {}

export const AvatarImage = React.forwardRef<HTMLImageElement, AvatarImageProps>(
  ({ src, alt = "Avatar", className = "", ...props }, ref) => {
    const { setImageLoaded, setImageError, imageError } = useAvatar();

    if (!src || imageError) return null;

    return (
      <img
        ref={ref}
        src={src}
        alt={alt}
        onLoad={() => setImageLoaded(true)}
        onError={() => setImageError(true)}
        className={`w-full h-full object-cover rounded-full ${className}`}
        {...props}
      />
    );
  }
);
AvatarImage.displayName = "AvatarImage";

export interface AvatarFallbackProps
  extends React.HTMLAttributes<HTMLDivElement> {
  initials?: string;
}

export const AvatarFallback = React.forwardRef<
  HTMLDivElement,
  AvatarFallbackProps
>(({ initials, className = "", children, ...props }, ref) => {
  const { size, imageLoaded, imageError } = useAvatar();

  if (imageLoaded && !imageError) return null;

  return (
    <div
      ref={ref}
      aria-hidden="true"
      className={`flex w-full h-full items-center justify-center rounded-full bg-slate-200 dark:bg-slate-800 text-slate-700 dark:text-slate-300 font-semibold uppercase ${sizeClasses[size].text} ${className}`}
      {...props}
    >
      {initials ? initials.slice(0, 2) : children}
    </div>
  );
});
AvatarFallback.displayName = "AvatarFallback";

export interface AvatarBadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  status?: AvatarStatus;
}

export const AvatarBadge = React.forwardRef<HTMLSpanElement, AvatarBadgeProps>(
  ({ status = "online", className = "", ...props }, ref) => {
    const { size } = useAvatar();

    return (
      <span
        ref={ref}
        aria-label={`Status: ${status}`}
        className={`absolute rounded-full border-2 border-background ring-1 ring-black/5 dark:ring-white/5 ${sizeClasses[size].badge} ${statusColors[status]} ${className}`}
        {...props}
      />
    );
  }
);
AvatarBadge.displayName = "AvatarBadge";

seam-status.content:
import * as React from "react";
import { ShieldCheck, AlertTriangle, CheckCircle2, ChevronRight, X } from "lucide-react";

export interface SeamContractField {
  frontendKey: string;
  backendKey: string;
  type?: string;
  required?: boolean;
  status: "synced" | "casing_drift" | "missing" | "extra";
}

export interface SeamContractEndpoint {
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  path: string;
  backendModel?: string;
  status: "synced" | "drift_detected" | "unverified";
  fields?: SeamContractField[];
}

export interface SeamStatusProps extends React.HTMLAttributes<HTMLDivElement> {
  endpoint?: SeamContractEndpoint;
  endpoints?: SeamContractEndpoint[];
  variant?: "pill" | "banner" | "card";
  showInspectorOnClick?: boolean;
}

export const SeamStatus = React.forwardRef<HTMLDivElement, SeamStatusProps>(
  (
    {
      endpoint,
      endpoints,
      variant = "pill",
      showInspectorOnClick = true,
      className = "",
      ...props
    },
    ref
  ) => {
    const [inspectorOpen, setInspectorOpen] = React.useState(false);

    const items = React.useMemo(() => {
      if (endpoints && endpoints.length > 0) return endpoints;
      if (endpoint) return [endpoint];
      return [
        {
          method: "POST" as const,
          path: "/v1/interviews/{session_id}/feedback",
          backendModel: "SubmitTeamFeedbackRequest",
          status: "synced" as const,
          fields: [
            { frontendKey: "scores", backendKey: "scores", status: "synced" as const, required: true },
            { frontendKey: "strengths", backendKey: "strengths", status: "synced" as const, required: true },
            { frontendKey: "improvements", backendKey: "improvements", status: "synced" as const, required: true },
            { frontendKey: "recommendations", backendKey: "recommendations", status: "synced" as const, required: true },
            { frontendKey: "detailed_feedback", backendKey: "detailed_feedback", status: "synced" as const, required: true },
          ],
        },
      ];
    }, [endpoint, endpoints]);

    const hasDrift = items.some((i) => i.status === "drift_detected");
    const activeItem = items[0];

    // Variant: Pill (Mini dev badge)
    if (variant === "pill") {
      return (
        <div ref={ref} className={`inline-block ${className}`} {...props}>
          <button
            type="button"
            onClick={() => showInspectorOnClick && setInspectorOpen(true)}
            className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium border transition-all cursor-pointer ${
              hasDrift
                ? "bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/20 hover:bg-red-500/15"
                : "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 border-emerald-500/20 hover:bg-emerald-500/15"
            }`}
          >
            {hasDrift ? (
              <AlertTriangle size={13} className="text-red-500 animate-pulse" />
            ) : (
              <ShieldCheck size={13} className="text-emerald-500" />
            )}
            <span>
              <strong>Seam:</strong> {hasDrift ? "Drift Detected" : "In Sync"}
            </span>
            <span className="text-[10px] font-mono opacity-70">
              {activeItem.method} {activeItem.path.split("/").slice(-1)[0]}
            </span>
          </button>

          {inspectorOpen && (
            <SeamInspectorModal
              items={items}
              onClose={() => setInspectorOpen(false)}
            />
          )}
        </div>
      );
    }

    // Variant: Banner (Form header callout)
    if (variant === "banner") {
      return (
        <>
          <div
            ref={ref}
            className={`flex items-center justify-between p-3.5 rounded-xl border text-xs ${
              hasDrift
                ? "bg-red-500/5 text-red-900 dark:text-red-200 border-red-500/20"
                : "bg-emerald-500/5 text-emerald-950 dark:text-emerald-100 border-emerald-500/20"
            } ${className}`}
            {...props}
          >
            <div className="flex items-center gap-2.5">
              <div
                className={`w-7 h-7 rounded-lg flex items-center justify-center shrink-0 ${
                  hasDrift
                    ? "bg-red-500/15 text-red-500"
                    : "bg-emerald-500/15 text-emerald-500"
                }`}
              >
                {hasDrift ? <AlertTriangle size={15} /> : <ShieldCheck size={15} />}
              </div>
              <div>
                <p className="font-semibold text-foreground">
                  Contract Verified:{" "}
                  <code className="px-1.5 py-0.5 rounded bg-black/5 dark:bg-white/10 font-mono text-[11px]">
                    {activeItem.method} {activeItem.path}
                  </code>
                </p>
                <p className="text-muted-foreground text-[11px]">
                  {hasDrift
                    ? "Casing or field discrepancies detected with FastAPI model."
                    : `Zero drift. Matched with ${activeItem.backendModel || "FastAPI schema"}.`}
                </p>
              </div>
            </div>

            {showInspectorOnClick && (
              <button
                type="button"
                onClick={() => setInspectorOpen(true)}
                className="text-xs font-semibold text-emerald-600 dark:text-emerald-400 hover:underline flex items-center gap-1"
              >
                <span>Inspect</span>
                <ChevronRight size={13} />
              </button>
            )}
          </div>

          {inspectorOpen && (
            <SeamInspectorModal
              items={items}
              onClose={() => setInspectorOpen(false)}
            />
          )}
        </>
      );
    }

    // Default: Card
    return (
      <div
        ref={ref}
        className={`p-4 rounded-xl border border-border bg-card space-y-3 ${className}`}
        {...props}
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ShieldCheck size={16} className="text-emerald-500" />
            <h4 className="text-xs font-bold uppercase tracking-wider text-muted-foreground">
              Contract Parity Status
            </h4>
          </div>
          <span className="text-[10px] font-mono px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-500 font-bold">
            Pydantic Sync
          </span>
        </div>

        <div className="space-y-1.5 font-mono text-xs">
          {items.map((it, idx) => (
            <div
              key={idx}
              className="flex items-center justify-between p-2 rounded-lg bg-muted/50 border border-border/50 text-[11px]"
            >
              <div className="flex items-center gap-2 truncate">
                <span className="font-bold text-emerald-500">{it.method}</span>
                <span className="text-foreground truncate">{it.path}</span>
              </div>
              <span className="text-xs text-emerald-500">✔ 0 drift</span>
            </div>
          ))}
        </div>
      </div>
    );
  }
);
SeamStatus.displayName = "SeamStatus";

// ─── INSPECTOR MODAL ─────────────────────────────────────────────────────────

function SeamInspectorModal({
  items,
  onClose,
}: {
  items: SeamContractEndpoint[];
  onClose: () => void;
}) {
  const [selectedIdx, setSelectedIdx] = React.useState(0);
  const active = items[selectedIdx] || items[0];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="w-full max-w-2xl bg-card border border-border rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[85vh]">
        {/* Header */}
        <div className="flex items-center justify-between p-5 border-b border-border bg-muted/30">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-emerald-500/10 text-emerald-500 flex items-center justify-center">
              <ShieldCheck size={20} />
            </div>
            <div>
              <h3 className="text-sm font-bold text-foreground">
                Seam Check Inspector
              </h3>
              <p className="text-xs text-muted-foreground">
                Runtime frontend ↔ FastAPI contract analyzer
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition"
          >
            <X size={16} />
          </button>
        </div>

        {/* Endpoint Selector Tabs (if multiple endpoints provided) */}
        {items.length > 1 && (
          <div className="flex items-center gap-1.5 px-6 pt-3 pb-2 border-b border-border/60 overflow-x-auto bg-muted/10">
            {items.map((it, idx) => (
              <button
                key={idx}
                type="button"
                onClick={() => setSelectedIdx(idx)}
                className={`px-2.5 py-1 rounded-lg text-xs font-mono font-medium transition whitespace-nowrap ${
                  selectedIdx === idx
                    ? "bg-foreground text-background font-bold shadow-sm"
                    : "bg-muted/50 text-muted-foreground hover:bg-muted hover:text-foreground"
                }`}
              >
                <span className="font-bold opacity-80 mr-1.5">{it.method}</span>
                {it.path}
              </button>
            ))}
          </div>
        )}

        {/* Content */}
        <div className="p-6 space-y-5 overflow-y-auto flex-1">
          {/* Endpoint Card */}
          <div className="p-3.5 rounded-xl bg-muted/40 border border-border flex items-center justify-between">
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <span className="px-2 py-0.5 rounded text-[10px] font-bold font-mono bg-emerald-500/20 text-emerald-400">
                  {active.method}
                </span>
                <span className="text-sm font-mono font-bold text-foreground">
                  {active.path}
                </span>
              </div>
              <p className="text-xs text-muted-foreground">
                Target Backend Model:{" "}
                <strong className="text-foreground">
                  {active.backendModel || "Pydantic Schema"}
                </strong>
              </p>
            </div>
            <span className="px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-500/10 text-emerald-500 border border-emerald-500/20">
              Verified In Sync
            </span>
          </div>

          {/* Field Table */}
          {active.fields && active.fields.length > 0 && (
            <div className="space-y-2">
              <h4 className="text-xs font-bold uppercase tracking-wider text-muted-foreground">
                Payload Contract Mapping ({active.fields.length} Fields)
              </h4>
              <div className="border border-border rounded-xl overflow-hidden text-xs">
                <table className="w-full text-left">
                  <thead className="bg-muted/50 border-b border-border text-muted-foreground font-semibold">
                    <tr>
                      <th className="p-2.5">Frontend Key</th>
                      <th className="p-2.5">Backend Field</th>
                      <th className="p-2.5">Required</th>
                      <th className="p-2.5">Parity</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border">
                    {active.fields.map((f, i) => (
                      <tr key={i} className="hover:bg-muted/30">
                        <td className="p-2.5 font-mono text-emerald-500 dark:text-emerald-400 font-semibold">
                          {f.frontendKey}
                        </td>
                        <td className="p-2.5 font-mono text-foreground">
                          {f.backendKey}
                        </td>
                        <td className="p-2.5">
                          {f.required ? (
                            <span className="text-amber-500 font-semibold">Yes</span>
                          ) : (
                            <span className="text-muted-foreground">Optional</span>
                          )}
                        </td>
                        <td className="p-2.5">
                          <span className="inline-flex items-center gap-1 text-emerald-500 font-semibold">
                            <CheckCircle2 size={13} />
                            <span>100% Match</span>
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-border bg-muted/20 flex items-center justify-between text-xs">
          <span className="text-muted-foreground">
            Run <code className="text-emerald-500">npx mintforge check</code> in CI for automated enforcement.
          </span>
          <button
            onClick={onClose}
            className="px-4 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white font-semibold transition"
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
}

alert-dialog.content:
"use client";

import * as React from "react";

interface AlertDialogContextType {
  open: boolean;
  setOpen: (open: boolean) => void;
  titleId: string;
  descriptionId: string;
}

const AlertDialogContext = React.createContext<AlertDialogContextType | null>(null);

function useAlertDialog() {
  const context = React.useContext(AlertDialogContext);
  if (!context) {
    throw new Error("AlertDialog components must be used within an <AlertDialog />");
  }
  return context;
}

export interface AlertDialogProps {
  children: React.ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export function AlertDialog({
  children,
  open: controlledOpen,
  onOpenChange,
}: AlertDialogProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(false);
  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : uncontrolledOpen;
  const titleId = React.useId();
  const descriptionId = React.useId();

  const setOpen = React.useCallback(
    (nextOpen: boolean) => {
      if (!isControlled) setUncontrolledOpen(nextOpen);
      onOpenChange?.(nextOpen);
    },
    [isControlled, onOpenChange]
  );

  return (
    <AlertDialogContext.Provider value={{ open, setOpen, titleId, descriptionId }}>
      {children}
    </AlertDialogContext.Provider>
  );
}

export interface AlertDialogTriggerProps {
  asChild?: boolean;
  children: React.ReactElement<{ onClick?: React.MouseEventHandler }>;
}

export function AlertDialogTrigger({ children }: AlertDialogTriggerProps) {
  const { setOpen } = useAlertDialog();

  return React.cloneElement(children, {
    onClick: (e: React.MouseEvent) => {
      children.props.onClick?.(e);
      setOpen(true);
    },
  });
}

export interface AlertDialogContentProps
  extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
}

export const AlertDialogContent = React.forwardRef<
  HTMLDivElement,
  AlertDialogContentProps
>(({ className = "", children, ...props }, ref) => {
  const { open, setOpen, titleId, descriptionId } = useAlertDialog();

  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    if (open) {
      document.body.style.overflow = "hidden";
      window.addEventListener("keydown", handleKeyDown);
    }
    return () => {
      document.body.style.overflow = "unset";
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [open, setOpen]);

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div
        className="fixed inset-0 bg-black/70 backdrop-blur-sm animate-in fade-in duration-150"
        onClick={() => setOpen(false)}
      />

      {/* Dialog Body */}
      <div
        ref={ref}
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descriptionId}
        className={`relative z-10 w-full max-w-md rounded-2xl border border-border bg-card p-6 shadow-2xl text-card-foreground animate-in zoom-in-95 duration-150 focus:outline-none ${className}`}
        {...props}
      >
        {children}
      </div>
    </div>
  );
});
AlertDialogContent.displayName = "AlertDialogContent";

export function AlertDialogHeader({
  className = "",
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={`flex flex-col space-y-2 text-left mb-5 ${className}`}
      {...props}
    />
  );
}

export function AlertDialogTitle({
  className = "",
  children,
  ...props
}: React.HTMLAttributes<HTMLHeadingElement>) {
  const { titleId } = useAlertDialog();
  return (
    <h3
      id={titleId}
      className={`text-base font-bold text-foreground flex items-center gap-2 ${className}`}
      {...props}
    >
      {children}
    </h3>
  );
}

export function AlertDialogDescription({
  className = "",
  children,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  const { descriptionId } = useAlertDialog();
  return (
    <p
      id={descriptionId}
      className={`text-xs text-muted-foreground leading-relaxed ${className}`}
      {...props}
    >
      {children}
    </p>
  );
}

export function AlertDialogFooter({
  className = "",
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={`flex items-center justify-end gap-2.5 pt-4 border-t border-border mt-5 ${className}`}
      {...props}
    />
  );
}

export type AlertDialogCancelProps =
  React.ButtonHTMLAttributes<HTMLButtonElement>;

export const AlertDialogCancel = React.forwardRef<
  HTMLButtonElement,
  AlertDialogCancelProps
>(({ className = "", children = "Cancel", onClick, ...props }, ref) => {
  const { setOpen } = useAlertDialog();

  return (
    <button
      ref={ref}
      type="button"
      onClick={(e) => {
        onClick?.(e);
        setOpen(false);
      }}
      className={`px-3.5 py-2 text-xs font-semibold rounded-lg border border-border bg-background text-foreground hover:bg-muted transition cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${className}`}
      {...props}
    >
      {children}
    </button>
  );
});
AlertDialogCancel.displayName = "AlertDialogCancel";

export interface AlertDialogActionProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "default" | "destructive";
}

export const AlertDialogAction = React.forwardRef<
  HTMLButtonElement,
  AlertDialogActionProps
>(
  (
    {
      variant = "default",
      className = "",
      children = "Continue",
      onClick,
      ...props
    },
    ref
  ) => {
    const { setOpen } = useAlertDialog();

    const variantStyles = {
      default:
        "bg-primary text-primary-foreground hover:bg-primary-hover shadow-sm",
      destructive:
        "bg-red-600 text-white hover:bg-red-700 shadow-sm focus-visible:ring-red-500",
    };

    return (
      <button
        ref={ref}
        type="button"
        onClick={(e) => {
          onClick?.(e);
          setOpen(false);
        }}
        className={`px-4 py-2 text-xs font-semibold rounded-lg transition cursor-pointer focus-visible:outline-none focus-visible:ring-2 ${variantStyles[variant]} ${className}`}
        {...props}
      >
        {children}
      </button>
    );
  }
);
AlertDialogAction.displayName = "AlertDialogAction";

bubble.content:
"use client";

import * as React from "react";
import {
  Bot,
  User,
  Copy,
  Check,
  ChevronDown,
  ChevronRight,
  Sparkles,
  ShieldCheck,
  RotateCw,
} from "lucide-react";

export type BubbleRole = "user" | "assistant" | "system";

export interface BubbleProps extends React.HTMLAttributes<HTMLDivElement> {
  role?: BubbleRole;
  avatar?: React.ReactNode;
  isStreaming?: boolean;
  seamVerified?: boolean;
  seamEndpoint?: string;
  onCopy?: () => void;
  onRetry?: () => void;
}

export const Bubble = React.forwardRef<HTMLDivElement, BubbleProps>(
  (
    {
      role = "assistant",
      avatar,
      isStreaming = false,
      seamVerified = false,
      seamEndpoint,
      onCopy,
      onRetry,
      className = "",
      children,
      ...props
    },
    ref
  ) => {
    const isUser = role === "user";
    const [copied, setCopied] = React.useState(false);

    const handleCopy = () => {
      if (typeof window !== "undefined" && navigator.clipboard) {
        const textToCopy = typeof children === "string" ? children : "";
        if (textToCopy) {
          navigator.clipboard.writeText(textToCopy);
        }
      }
      setCopied(true);
      onCopy?.();
      setTimeout(() => setCopied(false), 2000);
    };

    return (
      <div
        ref={ref}
        className={`flex items-start gap-3 w-full group ${
          isUser ? "flex-row-reverse" : "flex-row"
        } ${className}`}
        {...props}
      >
        {/* Avatar */}
        <div className="shrink-0 mt-0.5">
          {avatar !== undefined ? (
            avatar
          ) : (
            <div
              className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-semibold shadow-xs ${
                isUser
                  ? "bg-primary text-primary-foreground"
                  : "bg-emerald-500/10 text-emerald-500 border border-emerald-500/20"
              }`}
            >
              {isUser ? <User size={15} /> : <Bot size={15} />}
            </div>
          )}
        </div>

        {/* Message Container */}
        <div
          className={`flex flex-col gap-1.5 max-w-[85%] sm:max-w-[75%] ${
            isUser ? "items-end" : "items-start"
          }`}
        >
          {/* Main Bubble */}
          <div
            className={`rounded-2xl px-4 py-3 text-sm leading-relaxed transition-all shadow-xs ${
              isUser
                ? "bg-primary text-primary-foreground rounded-tr-xs"
                : "bg-card border border-border text-foreground rounded-tl-xs"
            }`}
          >
            {children}

            {/* Streaming Cursor */}
            {isStreaming && (
              <span className="inline-block w-1.5 h-4 ml-1 bg-emerald-500 align-middle animate-pulse" />
            )}
          </div>

          {/* Assistant Footnote: Actions & Seam Check Status */}
          {!isUser && (
            <div className="flex items-center gap-3 px-1 text-xs text-muted-foreground">
              {/* Seam Contract Parity Badge */}
              {seamVerified && (
                <div className="inline-flex items-center gap-1 text-[11px] font-mono text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 border border-emerald-500/20 px-2 py-0.5 rounded-full">
                  <ShieldCheck size={12} />
                  <span>Seam Verified</span>
                  {seamEndpoint && (
                    <span className="opacity-75">({seamEndpoint})</span>
                  )}
                </div>
              )}

              {/* Action Buttons */}
              <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                <button
                  type="button"
                  onClick={handleCopy}
                  title="Copy text"
                  className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition"
                >
                  {copied ? <Check size={13} className="text-emerald-500" /> : <Copy size={13} />}
                </button>
                {onRetry && (
                  <button
                    type="button"
                    onClick={onRetry}
                    title="Retry generation"
                    className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition"
                  >
                    <RotateCw size={13} />
                  </button>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }
);
Bubble.displayName = "Bubble";

// ─── BUBBLE THINKING (REASONING DRAWER) ───────────────────────────────────────

export interface BubbleThinkingProps
  extends React.HTMLAttributes<HTMLDivElement> {
  defaultOpen?: boolean;
  duration?: string;
  title?: string;
}

export function BubbleThinking({
  defaultOpen = false,
  duration,
  title = "Thinking Process",
  className = "",
  children,
  ...props
}: BubbleThinkingProps) {
  const [isOpen, setIsOpen] = React.useState(defaultOpen);

  return (
    <div
      className={`w-full rounded-xl border border-border/80 bg-muted/40 overflow-hidden mb-2 text-xs ${className}`}
      {...props}
    >
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center justify-between w-full px-3 py-2 text-left text-muted-foreground hover:text-foreground hover:bg-muted/60 transition font-medium"
      >
        <div className="flex items-center gap-2">
          <Sparkles size={13} className="text-amber-500" />
          <span>{title}</span>
          {duration && (
            <span className="text-[10px] text-muted-foreground font-mono">
              ({duration})
            </span>
          )}
        </div>
        {isOpen ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
      </button>

      {isOpen && (
        <div className="px-3.5 pb-3 pt-1 border-t border-border/50 text-muted-foreground font-mono text-[11px] leading-relaxed whitespace-pre-wrap animate-in fade-in-50 duration-150">
          {children}
        </div>
      )}
    </div>
  );
}

seam-form.content:
"use client";

import * as React from "react";
import { AlertTriangle } from "lucide-react";
import { SeamStatus, SeamContractEndpoint } from "./seam-status";

interface SeamFormContextValue {
  endpoint: string;
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  backendModel?: string;
  expectedFields?: string[];
  registeredFields: Record<string, boolean>;
  registerField: (name: string) => void;
}

const SeamFormContext = React.createContext<SeamFormContextValue | null>(null);

export function useSeamForm() {
  return React.useContext(SeamFormContext);
}

export interface SeamFormProps
  extends React.FormHTMLAttributes<HTMLFormElement> {
  endpoint: string;
  method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  backendModel?: string;
  expectedFields?: string[];
  showSeamBadge?: boolean;
}

export const SeamForm = React.forwardRef<HTMLFormElement, SeamFormProps>(
  (
    {
      endpoint,
      method = "POST",
      backendModel,
      expectedFields = [],
      showSeamBadge = true,
      className = "",
      children,
      onSubmit,
      ...props
    },
    ref
  ) => {
    const [registeredFields, setRegisteredFields] = React.useState<
      Record<string, boolean>
    >({});

    const registerField = React.useCallback((name: string) => {
      setRegisteredFields((prev) => {
        if (prev[name]) return prev;
        return { ...prev, [name]: true };
      });
    }, []);

    // Check for casing drift: if expected fields are snake_case, but form field is camelCase
    const detectedDrifts = React.useMemo(() => {
      const drifts: { field: string; suggestion: string }[] = [];
      const fieldNames = Object.keys(registeredFields);

      for (const name of fieldNames) {
        // camelCase detected in name
        if (/[a-z][A-Z]/.test(name)) {
          const snake = name.replace(/([A-Z])/g, "_$1").toLowerCase();
          if (expectedFields.includes(snake)) {
            drifts.push({ field: name, suggestion: snake });
          }
        }
      }
      return drifts;
    }, [registeredFields, expectedFields]);

    const endpointData: SeamContractEndpoint = React.useMemo(
      () => ({
        method,
        path: endpoint,
        backendModel,
        status: detectedDrifts.length > 0 ? "drift_detected" : "synced",
        fields: Object.keys(registeredFields).map((f) => {
          const drift = detectedDrifts.find((d) => d.field === f);
          return {
            frontendKey: f,
            backendKey: drift ? drift.suggestion : f,
            status: drift ? "casing_drift" : "synced",
            required: expectedFields.includes(f) || (drift ? expectedFields.includes(drift.suggestion) : false),
          };
        }),
      }),
      [method, endpoint, backendModel, registeredFields, detectedDrifts, expectedFields]
    );

    const contextValue = React.useMemo(
      () => ({
        endpoint,
        method,
        backendModel,
        expectedFields,
        registeredFields,
        registerField,
      }),
      [endpoint, method, backendModel, expectedFields, registeredFields, registerField]
    );

    return (
      <SeamFormContext.Provider value={contextValue}>
        <form
          ref={ref}
          onSubmit={onSubmit}
          className={`space-y-5 ${className}`}
          {...props}
        >
          {/* Seam Contract Header Banner */}
          {showSeamBadge && (
            <div className="space-y-2">
              <SeamStatus
                variant="banner"
                endpoint={endpointData}
                showInspectorOnClick={true}
              />

              {detectedDrifts.length > 0 && (
                <div className="p-3 rounded-xl bg-amber-500/10 border border-amber-500/20 text-xs text-amber-700 dark:text-amber-300 flex items-start gap-2 animate-in fade-in duration-200">
                  <AlertTriangle size={15} className="shrink-0 mt-0.5 text-amber-500" />
                  <div>
                    <strong className="font-semibold">Contract Casing Warning:</strong>
                    <ul className="list-disc list-inside mt-1 space-y-0.5 font-mono text-[11px]">
                      {detectedDrifts.map((d, i) => (
                        <li key={i}>
                          Form field &quot;{d.field}&quot; may cause HTTP 422. Expected backend parameter: &quot;{d.suggestion}&quot;.
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              )}
            </div>
          )}

          {children}
        </form>
      </SeamFormContext.Provider>
    );
  }
);
SeamForm.displayName = "SeamForm";

// ─── SEAM FORM FIELD ─────────────────────────────────────────────────────────

export interface SeamFormFieldProps
  extends React.HTMLAttributes<HTMLDivElement> {
  name: string;
  label?: string;
  required?: boolean;
}

export function SeamFormField({
  name,
  label,
  required,
  className = "",
  children,
  ...props
}: SeamFormFieldProps) {
  const ctx = useSeamForm();
  const registerField = ctx?.registerField;

  React.useEffect(() => {
    if (registerField && name) {
      registerField(name);
    }
  }, [registerField, name]);

  const isCamel = /[a-z][A-Z]/.test(name);
  const snakeSuggestion = name.replace(/([A-Z])/g, "_$1").toLowerCase();
  const hasExpectedSnake = ctx?.expectedFields?.includes(snakeSuggestion);

  return (
    <div className={`space-y-1.5 ${className}`} {...props}>
      <div className="flex items-center justify-between">
        {label && (
          <label className="text-xs font-semibold text-foreground flex items-center gap-1 select-none">
            <span>{label}</span>
            {required && <span className="text-red-500">*</span>}
          </label>
        )}

        {/* Casing Drift Indicator Pill */}
        {isCamel && hasExpectedSnake && (
          <span className="text-[10px] font-mono text-amber-600 dark:text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded border border-amber-500/20">
            Hint: backend uses {snakeSuggestion}
          </span>
        )}
      </div>

      {children}
    </div>
  );
}
